local function getConfigs(item: Instance, deserializer: (data: any) -> {}): IConfigurationSource?
	local type = typeof(item)
	assert(type == "Instance", "Item type should be Instance")

	local isType
	if deserializer then
		isType = "Factory"
	else
		if item:IsA("ModuleScript") then
			isType = "Module"
		else
			error("Deserializer is required for non-ModuleScript item:" .. item.Name)
		end
	end

	return {
		Instance = item,
		Type = isType,
		Name = item.Name,
		Factory = deserializer,
	}
end

return getConfigs
